import sys

points = {'posted': 15, 'commented': 10, 'likes': 5}

def main():
    input = sys.stdin.read().strip().split('\n')
    my_name = input[0]
    n = int(input[1])
    actions = input[2:]

    priority = {}

    for action in actions:
        parts = action.split()
        if parts[0] == my_name:
            target = parts[-1][:-2]
            if target not in priority:
                priority[target] = 0
            priority[target] += points[parts[1]]
        elif parts[-1][:-2] == my_name:
            actor = parts[0]
            if actor not in priority:
                priority[actor] = 0
            priority[actor] += points[parts[1]]

    result = sorted(priority.items(), key=lambda x: (-x[1], x[0]))

    for name, _ in result:
        print(name)

main()
